mapper.select:

where test_id = #{testId}
  and user_info_id = #{userInfoId}
  and status = 0
order by update_time desc, id desc
limit 1

mapper.update:
update personality_test_attempt
status = #{status}, answered_count = #{answeredCount}, current_question_no = #{currentQuestionNo}, completed_at = #{completedAt}, update_time = #{updateTime},
where id = #{id}
